import{Bt as e,Q as t,ht as n,nt as r,o as i,rt as a,tt as o}from"./chunks/framework.BDx6F-5s.js";import"./chunks/assets.CyQiMml3.js";var s=JSON.parse(`{"title":"Scenario Recording & Studio Guide","description":"Record web browser interactions in real-time, configure wait conditions, assertions, and recovery scripts for reliable test scenarios.","frontmatter":{"title":"Scenario Recording & Studio Guide","description":"Record web browser interactions in real-time, configure wait conditions, assertions, and recovery scripts for reliable test scenarios.","sort":300,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/scenario-create.html"}]]},"headers":[],"relativePath":"en/synceta/scenario-create.md","filePath":"en/synceta/scenario-create.md","lastUpdated":1787441312000}`),c={name:`en/synceta/scenario-create.md`};function l(i,s,c,l,u,d){return n(),o(`div`,null,[s[7]||=r(`<h1 id="scenario-recording-studio-guide" tabindex="-1">Scenario Recording &amp; Studio Guide <a class="header-anchor" href="#scenario-recording-studio-guide" aria-label="Permalink to “Scenario Recording &amp; Studio Guide”">​</a></h1><p>The SyncETA Studio captures browser actions (clicks, keyboard input, page navigation) and structures them with DOM details (XPath, CSS selectors, tag attributes) into automated test cases.</p><hr><h2 id="_1-scenario-definition" tabindex="-1">1. Scenario Definition <a class="header-anchor" href="#_1-scenario-definition" aria-label="Permalink to “1. Scenario Definition”">​</a></h2><p>A <strong>&#39;Scenario&#39;</strong> represents an end-to-end user workflow.</p><p>Example: <code>E-Commerce Search &amp; Cart Checkout</code></p><ol><li>Navigate to homepage</li><li>Click search box and input <code>Wireless Mouse</code></li><li>Submit search query</li><li>Click first product from search results</li><li>Click &#39;Add to Cart&#39; and verify confirmation modal</li></ol><hr><h2 id="_2-recording-workflow" tabindex="-1">2. Recording Workflow <a class="header-anchor" href="#_2-recording-workflow" aria-label="Permalink to “2. Recording Workflow”">​</a></h2><h3 id="step-1-open-scenario-creator" tabindex="-1">Step 1: Open Scenario Creator <a class="header-anchor" href="#step-1-open-scenario-creator" aria-label="Permalink to “Step 1: Open Scenario Creator”">​</a></h3><p>Navigate to <strong>&#39;Scenarios&#39;</strong> ➔ click <strong>&#39;New Scenario&#39;</strong>.</p><p><img src="/docs/assets/new_scenario.CxnBoB7X.png" alt="New Scenario" loading="lazy"></p><h3 id="step-2-configure-browser-viewport" tabindex="-1">Step 2: Configure Browser &amp; Viewport <a class="header-anchor" href="#step-2-configure-browser-viewport" aria-label="Permalink to “Step 2: Configure Browser &amp; Viewport”">​</a></h3><p>Set target URL, browser engine (Chrome/Edge), and viewport resolution.</p><p><img src="/docs/assets/select_option.BO9WUS-y.png" alt="Recording Settings" loading="lazy"></p><h3 id="step-3-event-filters" tabindex="-1">Step 3: Event Filters <a class="header-anchor" href="#step-3-event-filters" aria-label="Permalink to “Step 3: Event Filters”">​</a></h3><p>Select event types to capture (clicks, inputs, hover, scrolls). Default settings are recommended.</p><p><img src="/docs/assets/allow_event.BTzP3-1K.png" alt="Event Filter" loading="lazy"></p><h3 id="step-4-record-actions" tabindex="-1">Step 4: Record Actions <a class="header-anchor" href="#step-4-record-actions" aria-label="Permalink to “Step 4: Record Actions”">​</a></h3><p>Perform actions in the dedicated recording browser. Events appear in sequence below.</p><p><img src="/docs/assets/start_recording.C0eDEaiH.png" alt="Start Recording" loading="lazy"><img src="/docs/assets/select_dom_info.Dv7Rqw5o.png" alt="DOM Info Captured" loading="lazy"></p><hr><h2 id="_3-wait-conditions" tabindex="-1">3. Wait Conditions <a class="header-anchor" href="#_3-wait-conditions" aria-label="Permalink to “3. Wait Conditions”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th><th style="text-align:left;">Best Used For</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Fixed Timeout</strong></td><td style="text-align:left;">Pauses execution for a specified millisecond duration.</td><td style="text-align:left;">External API response latency</td></tr><tr><td style="text-align:left;"><strong>DOM Visible</strong></td><td style="text-align:left;">Waits until target element renders in DOM.</td><td style="text-align:left;">Dynamic modal popups</td></tr><tr><td style="text-align:left;"><strong>Value Match</strong></td><td style="text-align:left;">Waits until target element&#39;s text matches expected value.</td><td style="text-align:left;">Status change to &#39;Completed&#39;</td></tr></tbody></table><p><img src="/docs/assets/time_wait.Ck2J4xsR.png" alt="Time Wait" loading="lazy"><img src="/docs/assets/dom_wait.DhHz2jZ9.png" alt="DOM Wait" loading="lazy"><img src="/docs/assets/value_wait.97BmEy8x.png" alt="Value Wait" loading="lazy"></p><hr><h2 id="_4-assertions" tabindex="-1">4. Assertions <a class="header-anchor" href="#_4-assertions" aria-label="Permalink to “4. Assertions”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>DOM Visible Assertion</strong></td><td style="text-align:left;">Asserts that a target UI component is present on screen.</td></tr><tr><td style="text-align:left;"><strong>Value Assertion</strong></td><td style="text-align:left;">Asserts that text or attribute value matches expected string.</td></tr><tr><td style="text-align:left;"><strong>Vision AI Assertion</strong></td><td style="text-align:left;">Analyzes rendered screenshot to verify layout visual correctness.</td></tr></tbody></table><p><img src="/docs/assets/valid_dom.2uHkx6Bq.png" alt="DOM Assertion" loading="lazy"><img src="/docs/assets/valid_value.CTFJE1s6.png" alt="Value Assertion" loading="lazy"><img src="/docs/assets/valid_ai.BLlZ6YWJ.png" alt="Vision AI Assertion" loading="lazy"></p><hr><h2 id="_5-editing-additional-features" tabindex="-1">5. Editing &amp; Additional Features <a class="header-anchor" href="#_5-editing-additional-features" aria-label="Permalink to “5. Editing &amp; Additional Features”">​</a></h2>`,31),t(`ul`,null,[s[4]||=t(`li`,null,[t(`strong`,null,`Continue Recording`),a(`: Resume recording from a specific existing step. `),t(`img`,{src:`/docs/assets/edit.DharqlJd.png`,alt:`Edit`,loading:`lazy`})],-1),s[5]||=t(`li`,null,[t(`strong`,null,`Step Comments`),a(`: Attach documentation notes to individual steps. `),t(`img`,{src:`/docs/assets/comment.bH8IGTY6.png`,alt:`Comment`,loading:`lazy`})],-1),s[6]||=t(`li`,null,[t(`strong`,null,`Recovery Scripts`),a(`: Execute fallback JavaScript upon step failure. `),t(`img`,{src:`/docs/assets/recover.BpaZA4Gc.png`,alt:`Recovery`,loading:`lazy`})],-1),t(`li`,null,[s[0]||=t(`strong`,null,`Dataset Variables`,-1),s[1]||=a(`: Bind input fields to dynamic variables (`,-1),t(`code`,null,e(i.username),1),s[2]||=a(`). `,-1),s[3]||=t(`img`,{src:`/docs/assets/dataset.BNYNMS0h.png`,alt:`Dataset`,loading:`lazy`},null,-1)])])])}var u=i(c,[[`render`,l]]);export{s as __pageData,u as default};